'use strict';
const $ = (s,root=document)=>root.querySelector(s);
const $$ = (s,root=document)=>[...root.querySelectorAll(s)];
const icon=(name,cls='')=>`<svg class="icon ${cls}" aria-hidden="true"><use href="assets/icons.svg#i-${name}"></use></svg>`;
const arrow=()=>icon('arrow');
const logo=()=>`<a class="brand brand-image site-brand" href="index.html" aria-label="LittleRoute home"><span class="brand-mark"><img src="assets/littleroute-logo.png" alt="" width="80" height="80"></span><span class="brand-wordmark">Little<span class="brand-route">Route</span><small>SCHOOL DAYS START SAFELY</small></span></a>`;
const page=document.body.dataset.page;
const routes=[
{id:'LR-01',area:'Whitefield',school:'Westbridge Public School',distance:'0–5 km',fee:2400,departure:'7:20 am',arrival:'8:05 am',returnTime:'3:15 pm',duration:'45 min',seats:'Route preview',stops:[['Palm Meadows','7:20 am'],['Brookefield Junction','7:28 am'],['Greenwood Apartments','7:36 am'],['AECS Layout','7:44 am'],['Westbridge Public School','8:05 am']]},
{id:'LR-02',area:'Indiranagar',school:'Maple Grove Academy',distance:'5–10 km',fee:3200,departure:'7:10 am',arrival:'7:55 am',returnTime:'3:30 pm',duration:'45 min',seats:'Route preview',stops:[['100 Feet Road','7:10 am'],['Defence Colony','7:22 am'],['Domlur Park','7:32 am'],['Old Airport Road','7:42 am'],['Maple Grove Academy','7:55 am']]},
{id:'LR-03',area:'Sarjapur',school:'Greenfield International',distance:'10–15 km',fee:4100,departure:'6:55 am',arrival:'7:50 am',returnTime:'3:20 pm',duration:'55 min',seats:'Route preview',stops:[['Sarjapur Town','6:55 am'],['Carmelaram','7:09 am'],['Doddakannelli','7:22 am'],['Bellandur Junction','7:35 am'],['Greenfield International','7:50 am']]}
];
const money=n=>'₹'+Number(n).toLocaleString('en-IN');
const routeCard=r=>`<article class="route-card hover-card reveal"><div class="route-card-top"><span class="route-id">${icon('bus')}${r.id}</span><span class="small-label">${r.distance}</span></div><h3>${r.area}</h3><p class="school-name">${icon('pin')}${r.school}</p><div class="mini-route"><i></i><span>${r.stops[0][0]}</span><b>→</b><span>School</span></div><div class="route-times"><div><small>FIRST PICKUP</small><strong>${r.departure}</strong></div><div><small>SCHOOL ARRIVAL</small><strong>${r.arrival}</strong></div></div><button class="text-button" data-route="${r.id}">View stops & timings ${arrow()}</button></article>`;
const faqDesigns={home2:['journey','Journey questions'],services:['directory','Service notes'],routes:['stops','Coverage answers'],fees:['receipt','Fee questions'],safety:['checklist','Shared safety notes'],contact:['conversation','Here to help'],'daily-school-transport':['schedule','Daily travel questions'],'one-way-transport':['direction','One-way essentials'],'parent-transport-portal':['messages','Portal questions'],'student-safety-support':['care','Support answers']};
const faq=(items)=>{const [style,label]=faqDesigns[page]||['directory','Helpful answers'];return `<div class="faq-list faq-reviewed faq--${style}" aria-label="${label}">${items.map(([q,a],i)=>`<details class="faq-item"><summary><span class="faq-marker" aria-hidden="true">${String(i+1).padStart(2,'0')}</span><span class="faq-question">${q}</span><span class="faq-toggle" aria-hidden="true">${icon('plus')}</span></summary><div class="faq-answer"><p>${a}</p></div></details>`).join('')}</div>`;};
const eyebrow=t=>`<p class="eyebrow"><span></span>${t}</p>`;
